#!/usr/bin/env python3
import itertools
import json

# Input constraints
total_days = 20

# City information: duration is the required number of days in the city.
# If an event is specified, for Berlin we require that both required days occur,
# while for Barcelona and Lyon at least one of the required days must be in that city's range.
cities = {
    "Berlin": {"duration": 3, "events": {"conference": [1, 3]}},
    "Nice": {"duration": 5},
    "Athens": {"duration": 5},
    "Stockholm": {"duration": 5},
    "Barcelona": {"duration": 2, "events": {"workshop": [3, 4]}},
    "Vilnius": {"duration": 4},
    "Lyon": {"duration": 2, "events": {"wedding": [4, 5]}}
}

# Direct flight graph (bidirectional)
graph = {
    "Berlin": {"Athens", "Nice", "Barcelona", "Vilnius", "Stockholm"},
    "Nice": {"Lyon", "Athens", "Berlin", "Stockholm", "Barcelona"},
    "Athens": {"Stockholm", "Nice", "Berlin", "Vilnius", "Barcelona"},
    "Stockholm": {"Athens", "Berlin", "Nice", "Barcelona"},
    "Barcelona": {"Berlin", "Nice", "Athens", "Stockholm", "Lyon"},
    "Vilnius": {"Berlin", "Athens"},
    "Lyon": {"Nice", "Barcelona"}
}

def compute_schedule(order):
    """
    Given an ordering of cities, compute the day ranges for each city.
    The rule is:
      - For the first city, start on day 1.
      - For each city, the range is [start, start + duration - 1].
      - When flying from city A to city B on the same day,
        that day is double-counted (it is the finish day for A and the start day for B).
    """
    schedule = []
    start_day = 1
    for city in order:
        duration = cities[city]["duration"]
        finish_day = start_day + duration - 1
        schedule.append((city, start_day, finish_day))
        # Next city's start day is the finish day of the current city.
        start_day = finish_day
    return schedule

def check_events(schedule):
    """
    Check that scheduled day ranges for cities with events satisfy event constraints.
    For Berlin ("conference"), both day 1 and day 3 must be in the Berlin range.
    For Barcelona ("workshop"), at least one day among 3 or 4 must fall in its range.
    For Lyon ("wedding"), at least one day among 4 or 5 must fall in its range.
    """
    for city, start, finish in schedule:
        if "events" in cities[city]:
            days_in_city = set(range(start, finish + 1))
            for event, req_days in cities[city]["events"].items():
                req_day_set = set(req_days)
                # For Berlin we require both required days to be present.
                if city == "Berlin":
                    if not req_day_set.issubset(days_in_city):
                        return False
                else:
                    if not days_in_city.intersection(req_day_set):
                        return False
    return True

def valid_route(order):
    """
    Check if every consecutive city pair in 'order' has a direct flight.
    """
    for i in range(len(order) - 1):
        if order[i+1] not in graph[order[i]]:
            return False
    return True

def main():
    start_city = "Berlin"  # Berlin is fixed because of the conference on day 1 and day 3.
    remaining_cities = [city for city in cities if city != start_city]
    solution_schedule = None

    # Try all permutations of the remaining 6 cities.
    for perm in itertools.permutations(remaining_cities):
        order = (start_city,) + perm
        if not valid_route(order):
            continue
        schedule = compute_schedule(order)
        # Verify that the itinerary spans exactly the total_days.
        if schedule[-1][2] != total_days:
            continue
        if check_events(schedule):
            solution_schedule = schedule
            break

    if solution_schedule is None:
        output = {"itinerary": []}
    else:
        itinerary = []
        for city, start, finish in solution_schedule:
            itinerary.append({"day_range": f"Day {start}-{finish}", "place": city})
        output = {"itinerary": itinerary}
    print(json.dumps(output))

if __name__ == "__main__":
    main()
